import re


_CAPTURE = re.compile(r"\{([A-Za-z_]\w*)(\*)?\}\Z")


class CommandRouter:
    def __init__(self):
        self._routes = []

    @staticmethod
    def _segments(value):
        if not isinstance(value, str) or not value.startswith("/"):
            raise ValueError("path must start with /")
        if value == "/":
            return []
        if value.endswith("/") or "//" in value:
            raise ValueError("path contains an empty segment")
        return value[1:].split("/")

    def register(self, pattern, target):
        segments = self._segments(pattern)
        if not isinstance(target, str) or not target:
            raise ValueError("target must be a non-empty string")
        if any(existing[0] == pattern for existing in self._routes):
            raise ValueError("duplicate pattern")
        names = set()
        score = []
        for index, segment in enumerate(segments):
            match = _CAPTURE.fullmatch(segment)
            if match:
                name, star = match.groups()
                if name in names or (star and index != len(segments) - 1):
                    raise ValueError("invalid placeholder")
                names.add(name)
                score.append(0 if star else 1)
            else:
                if "{" in segment or "}" in segment:
                    raise ValueError("invalid pattern segment")
                score.append(2)
        self._routes.append((pattern, target, segments, tuple(score), len(self._routes)))

    def resolve(self, path):
        parts = self._segments(path)
        matches = []
        for _, target, pattern, score, order in self._routes:
            params = {}
            cursor = 0
            valid = True
            for segment in pattern:
                match = _CAPTURE.fullmatch(segment)
                if match and match.group(2):
                    if cursor >= len(parts):
                        valid = False
                        break
                    params[match.group(1)] = "/".join(parts[cursor:])
                    cursor = len(parts)
                elif cursor >= len(parts):
                    valid = False
                    break
                elif match:
                    params[match.group(1)] = parts[cursor]
                    cursor += 1
                elif segment == parts[cursor]:
                    cursor += 1
                else:
                    valid = False
                    break
            if valid and cursor == len(parts):
                matches.append((score, -order, target, params))
        if not matches:
            raise KeyError(path)
        _, _, target, params = max(matches, key=lambda item: (item[0], item[1]))
        return target, dict(params)


def make_inventory_router():
    router = CommandRouter()
    router.register("/items", "item_list")
    router.register("/items/{code}", "item_detail")
    router.register("/items/new", "item_create")
    router.register("/makers/new", "maker_create")
    router.register("/rooms/new", "room_create")
    router.register("/regions/new", "region_create")
    router.register("/assets/{path*}", "asset")
    return router
